<script setup>
import {ref,computed} from 'vue'
import {useRouter} from 'vue-router'
const router=useRouter(),island=ref(0),selected=ref(0),observing=ref(false),collected=ref([]),bag=ref(false),resting=ref(false),notice=ref(''),mapOpen=ref(true),atlasOpen=ref(true)
const islands=['萤火浅滩','雾屿回廊','星眠谷地','低语树畔']
const moods=[
 {name:'安宁',color:'#c9b4ef',text:'今天心里有一点安静，像月光落在没有波澜的水面。',hint:'不用说很多，陪它安静待一会儿就好。'},
 {name:'松弛',color:'#eed49a',text:'终于可以慢下来，肩膀也愿意松开一点点了。',hint:'这一刻，不需要再完成什么。'},
 {name:'思绪',color:'#a5d7ee',text:'今天心里有点乱，像风吹过好多想法。',hint:'先听听它想说什么，别急着走开。'},
 {name:'孤独',color:'#a6dce4',text:'想要一点陪伴，又不知道从哪一句说起。',hint:'不必马上开口，我可以在这里陪你。'},
 {name:'怅然',color:'#edb6d7',text:'有些没说出口的话，还轻轻停留在心里。',hint:'那些舍不得的感受，也有被安放的位置。'},
 {name:'期待',color:'#e9dca2',text:'明天会是什么样呢？我想给它留一盏小小的灯。',hint:'留一点期待，也给自己留一点从容。'}]
selected.value=2
const mood=computed(()=>moods[selected.value]),key=computed(()=>island.value+'-'+selected.value)
function choose(i){selected.value=i;observing.value=false;notice.value=''}
function give(){if(!collected.value.includes(key.value))collected.value.push(key.value);notice.value='这份心情已收到一颗温柔星。';observing.value=false}
function goIsland(i){island.value=i;choose((i+2)%moods.length)}
function item(name){notice.value=({星光瓶:'星光瓶里，装着你本次送出的 '+collected.value.length+' 颗温柔星。',梦笺:'把想说的话，带到星夜叙语慢慢写下。',风之铃:'先留意身边的一点声音，让思绪轻轻停靠。'})[name]}
</script>
<template>
 <section class="dream-roaming" aria-label="梦络漫游">
  <div class="roam-stars" aria-hidden="true"><i v-for="n in 40" :key="n" :style="{left:(n*37%100)+'%',top:(n*23%97)+'%',animationDelay:-(n%7)+'s'}">✦</i></div>
  <header class="roam-header"><h1>梦络漫游</h1><div class="roam-top-actions"><button aria-label="显示梦境地图" :aria-pressed="mapOpen" @click="mapOpen=!mapOpen">☷</button><button aria-label="显示梦络图鉴" :aria-pressed="atlasOpen" @click="atlasOpen=!atlasOpen">☆</button><button aria-label="和梦灵闲谈" @click="router.push('/dream/night-talk')">☏</button><button aria-label="打开背包" @click="bag=!bag">▢</button></div></header>
  <div class="roam-layout" :class="{'no-map':!mapOpen,'no-atlas':!atlasOpen}">
   <aside v-if="mapOpen" class="roam-map glass"><header><button class="round-icon" aria-label="返回梦境总览" @click="router.push('/dream')"><svg viewBox="0 0 24 24"><path d="m14 5-7 7 7 7"/></svg></button><h2>梦境地图</h2><button class="round-icon" aria-label="收起地图" @click="mapOpen=false">×</button></header><div class="island-path"><svg class="island-lines" viewBox="0 0 300 600" preserveAspectRatio="none" aria-hidden="true"><path d="M130 85Q260 150 215 235T85 365Q250 440 180 510"/></svg><button v-for="(name,i) in islands" :key="name" class="roam-island" :class="{active:island===i}" :aria-pressed="island===i" @click="goIsland(i)"><img :src="'/dream-roam/island-'+i+'.png'" alt=""><span>{{name}}</span><small v-if="island===i">梦络 {{collected.filter(k=>k.startsWith(i+'-')).length}} / 6</small></button></div><div class="roam-inventory"><button @click="bag=!bag">♧<span>背包</span></button><button v-for="(name,i) in ['星光瓶','梦笺','风之铃']" :key="name" @click="item(name)"><b>{{['♧','♢','♧'][i]}}</b><span>{{name}}</span></button></div></aside>
   <main class="roam-scene"><div class="roam-speech">{{resting?'慢慢呼吸，在这里休息一会儿。':mood.hint}}</div><img class="roam-spirit" src="/dream-roam/spirit.png" alt="长着星星触角的白色梦灵"><div class="shore" aria-hidden="true"></div><div class="mood-orbits" role="group" aria-label="选择情绪碎片"><button v-for="(m,i) in moods" :key="m.name" class="mood-orb" :class="['orb-'+i,{selected:selected===i}]" :style="{'--orb':m.color}" :aria-pressed="selected===i" @click="choose(i)">{{m.name}}</button></div><svg class="star-trail" viewBox="0 0 700 700" aria-hidden="true"><path d="M360 550Q600 620 490 280T350 450"/></svg><article class="fragment glass"><h2>情绪碎片</h2><div><p>它说：{{mood.text}}</p><p v-if="observing" class="observed">{{mood.hint}} 你可以只看着它，也可以把一颗温柔星交给它。</p><div class="fragment-actions"><button @click="observing=!observing">{{observing?'轻轻收起':'仔细观察'}}</button><button :disabled="collected.includes(key)" @click="give">{{collected.includes(key)?'已赠予温柔星':'赠予温柔星'}}</button></div></div></article><p v-if="notice" class="roam-notice" role="status">{{notice}}</p><button v-if="!mapOpen" class="restore-map" @click="mapOpen=true">展开梦境地图</button></main>
   <aside v-if="atlasOpen" class="roam-atlas glass"><header><h2>梦络图鉴</h2><button class="round-icon" aria-label="收起图鉴" @click="atlasOpen=false">×</button></header><p class="collection-count">已收集 {{collected.length}} / 24</p><div class="atlas-list"><button v-for="(m,i) in moods" :key="m.name" :class="{active:selected===i}" @click="choose(i)"><span :style="{'--orb':m.color}">✧</span><strong>{{m.name}}梦络</strong><small>{{collected.includes(island+'-'+i)?'♥':'♡'}}</small></button></div><article class="daily-note"><h3>今日小记事</h3><p>{{collected.length?'你接住了 '+collected.length+' 份情绪，今晚可以安心停留。':'遇见一份心情，慢慢听它说。不必急着收集。'}}</p><small>本次漫游记录 · 离开后重新开始</small><div aria-hidden="true">✧　✧　✧</div></article><div class="roam-bottom"><button @click="router.push('/dream')">←<span>返回导航</span></button><button @click="router.push('/dream/night-talk')">☏<span>和梦灵闲谈</span></button><button :aria-pressed="resting" @click="resting=!resting">☾<span>{{resting?'继续漫游':'休憩片刻'}}</span></button></div></aside>
  </div><div v-if="bag" class="bag-panel glass" role="dialog" aria-label="漫游背包"><button class="round-icon" aria-label="关闭背包" @click="bag=false">×</button><h2>我的星光背包</h2><p>本次已送出 {{collected.length}} 颗温柔星。</p><p v-if="!collected.length">遇见一份情绪，赠予温柔星后，它会留在这里。</p><ul v-else><li v-for="k in collected" :key="k">{{islands[Number(k.split('-')[0])]}} · {{moods[Number(k.split('-')[1])].name}}</li></ul></div>
 </section>
</template>
